config.content:
#ifdef __cplusplus
extern "C" {
#endif

#define SAU_LIN_CFG_PARAM_CHECKING_ENABLE    ${config.driver.sau_lin.param_checking_enable}
#define SAU_LIN_CFG_CHECKSUM_SUPPORT_ENABLE  ${config.driver.sau_lin.checksum_support}
#define SAU_LIN_CFG_MASTER_SUPPORT_ENABLE    ${config.driver.sau_lin.master_support}
#define SAU_LIN_CFG_SLAVE_SUPPORT_ENABLE     ${config.driver.sau_lin.slave_support}
#define SAU_LIN_CFG_WAKEUP_SUPPORT_ENABLE    ${config.driver.sau_lin.wakeup_support}
#define SAU_LIN_AUTO_SYNC_SUPPORT_ENABLE     ${config.driver.sau_lin.auto_synchronization_support}

#ifdef __cplusplus
}
#endif

module.header:
extern const lin_cfg_t ${module.driver.lin.name}_cfg;
/* LIN on SAU Instance. */
extern const lin_instance_t ${module.driver.lin.name};

#ifndef ${module.driver.lin.p_callback}
void ${module.driver.lin.p_callback}(lin_callback_args_t * p_args);
#endif

extern const sau_lin_extended_cfg_t ${module.driver.lin.name}_cfg_extend;
extern sau_lin_instance_ctrl_t ${module.driver.lin.name}_ctrl;

module.declarations:
#include "r_sau_lin_cfg.h"
sau_lin_instance_ctrl_t ${module.driver.lin.name}_ctrl;

sau_uart_baudrate_setting_t  ${module.driver.lin.name}_break_field_baud_setting =
{
     ${module.driver.sau_lin.break_field_baud},
     .operation_clock = ${module.driver.sau_lin.requires.sau_uart::module.driver.uart.operation_clock},
};

const sau_lin_extended_cfg_t ${module.driver.lin.name}_cfg_extend =
{
    .p_uart  = &${module.driver.sau_lin.requires.sau_uart::module.driver.uart.name},
#define RA_NOT_DEFINED (1)
#if (RA_NOT_DEFINED == ${module.driver.sau_lin.requires.icu::module.driver.external_irq.name})
    .p_icu   = NULL,
#else
    .p_icu   = &${module.driver.sau_lin.requires.icu::module.driver.external_irq.name},
#endif
#undef RA_NOT_DEFINED
#if SAU_LIN_CFG_MASTER_SUPPORT_ENABLE
    .p_break_field_baudrate = &${module.driver.lin.name}_break_field_baud_setting,
#endif
#if SAU_LIN_CFG_SLAVE_SUPPORT_ENABLE
    .p_timer = ${module.driver.sau.lin.timer},
    .timer_clock_frequency = ${module.driver.sau.lin.timer.clock},
    .auto_synchronization = ${module.driver.sau_lin.auto_synchronization},
#endif
};

const lin_cfg_t ${module.driver.lin.name}_cfg =
{
    .mode        = ${module.driver.sau_lin.mode},
    .p_callback  = ${module.driver.lin.p_callback},
    .p_extend    = &${module.driver.lin.name}_cfg_extend,
};

/* Instance structure to use this module. */
const lin_instance_t ${module.driver.lin.name} =
{
    .p_ctrl      = &${module.driver.lin.name}_ctrl,
    .p_cfg       = &${module.driver.lin.name}_cfg,
    .p_api       = &g_lin_on_sau_lin
};
